// Shows phone notifications on this device. Generated by Claude Opus 5.5, 2026/11/25
// Q. I need to set up notifications with android studio. I need to detect notifications from a Notifications
// document from firebase, and then send a local notification to the device when one of these notifications
// are created. How can I do this? I have provided the Notifications schema, and our current MainActivity.

package com.example.campsitereservationapp.ui.entrant.Notifications

import android.Manifest
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.core.content.ContextCompat
import com.example.campsitereservationapp.MainActivity
import com.example.campsitereservationapp.R

/**
 * Shows phone (system tray) notifications for this app.
 *
 * Call [createChannel] once at startup before calling [show].
 */
object LocalNotifier {
    private const val CHANNEL_ID = "app_notifications"

    /**
     * Registers the app's notification channel with Android. Required on Android 8+.
     * Safe to call more than once.
     *
     * @param context any context.
     */
    fun createChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(CHANNEL_ID, "Notifications", NotificationManager.IMPORTANCE_DEFAULT)
            context.getSystemService(NotificationManager::class.java).createNotificationChannel(channel)
        }
    }

    /**
     * Shows one phone notification. Tapping it opens the app.
     * Does nothing if the user has not allowed notifications.
     *
     * @param context any context.
     * @param id the Firestore notification document ID; used so each notification gets its own slot.
     * @param title the notification's title (the notification's subject).
     * @param text the notification's body (the notification's message).
     */
    fun show(context: Context, id: String, title: String, text: String) {
        if (ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS)
            != PackageManager.PERMISSION_GRANTED) return

        val intent = Intent(context, MainActivity::class.java)
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
        val pending = PendingIntent.getActivity(context, id.hashCode(), intent, PendingIntent.FLAG_IMMUTABLE)

        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.reboot_basecamp_icon)
            .setContentTitle(title)
            .setContentText(text)
            .setStyle(NotificationCompat.BigTextStyle().bigText(text))
            .setContentIntent(pending)
            .setAutoCancel(true)
            .build()

        NotificationManagerCompat.from(context).notify(id.hashCode(), notification)
    }
}
